#!/usr/bin/env python3
"""Generate docs/outputs.md from alien.schema so the output reference cannot drift from the code."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from alien.schema import CANONICAL_COLUMNS, OUTPUT_FILES, OUTPUT_SCHEMA_VERSION

ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / "docs" / "outputs.md"


def render() -> str:
    lines = [
        "# Output reference",
        "",
        "<!-- Generated by scripts/generate_outputs_doc.py from src/alien/schema.py; do not edit by hand. -->",
        "",
        f"Output schema version: **{OUTPUT_SCHEMA_VERSION}** (recorded in `MANIFEST.json` and "
        "`metadata/source_provenance.json`). It is bumped whenever a file or column changes incompatibly.",
        "",
        "Every build is written to a hidden staging directory beside `project.outdir`, pruned to the output mode, "
        "given a `MANIFEST.json`, and swapped into place atomically. A failed build leaves the previous output "
        "untouched and keeps its diagnostics under `<outdir>/failed/`. Tables are tab-separated; `.tsv.gz` files are "
        "gzip-compressed with a zero timestamp so identical builds give identical bytes.",
        "",
        "| File | Modes | Description |",
        "|---|---|---|",
    ]
    lines += [f"| `{f.path}` | {', '.join(f.modes)} | {f.description} |" for f in OUTPUT_FILES]
    lines += ["", "## Columns", ""]
    for output in OUTPUT_FILES:
        if output.columns:
            lines += [f"### `{output.path}`", "", ", ".join(f"`{c}`" for c in output.columns), ""]
    lines += [
        "## Canonical membership table",
        "",
        "Every source is normalized to these columns before mapping (one row per term and gene):",
        "",
        ", ".join(f"`{c}`" for c in CANONICAL_COLUMNS),
        "",
    ]
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if docs/outputs.md is out of date")
    args = parser.parse_args(argv)
    text = render()
    if args.check:
        if not TARGET.exists() or TARGET.read_text(encoding="utf-8") != text:
            print("docs/outputs.md is out of date; run python scripts/generate_outputs_doc.py", file=sys.stderr)
            return 1
        return 0
    TARGET.write_text(text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
